package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class TotpConfigService{private final PasswordVaultItemRepository items;private final PasswordVaultRepository vaults;private final TotpConfigRepository totps;public TotpConfigService(PasswordVaultItemRepository i,PasswordVaultRepository v,TotpConfigRepository t){items=i;vaults=v;totps=t;}public Mono<TotpConfigView> save(UUID a,UUID itemId,UpsertTotpRequest q){return item(a,itemId).flatMap(i->vaults.findById(i.vaultId()).filter(v->v.status()==PasswordVaultStatus.UNLOCKED).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 未解锁或不存在"))).flatMap(v->totps.findByItemIdAndOwnerId(itemId,a).flatMap(old->totps.save(new TotpConfigEntity(old.id(),old.itemId(),old.vaultId(),a,q.encryptedSecret(),q.algorithm()==null?TotpAlgorithm.SHA1:q.algorithm(),q.digits()==null?6:q.digits(),q.periodSeconds()==null?30:q.periodSeconds(),old.createdAt(),Instant.now(),old.version()))).switchIfEmpty(Mono.defer(()->totps.save(new TotpConfigEntity(null,itemId,i.vaultId(),a,q.encryptedSecret(),q.algorithm()==null?TotpAlgorithm.SHA1:q.algorithm(),q.digits()==null?6:q.digits(),q.periodSeconds()==null?30:q.periodSeconds(),Instant.now(),Instant.now(),null))))).map(this::view));}public Mono<TotpConfigView> get(UUID a,UUID itemId){return item(a,itemId).flatMap(i->totps.findByItemIdAndOwnerId(itemId,a)).map(this::view);}private Mono<PasswordVaultItemEntity> item(UUID a,UUID id){return items.findById(id).filter(i->i.ownerId().equals(a)&&!i.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问")));}private TotpConfigView view(TotpConfigEntity x){return new TotpConfigView(x.id(),x.itemId(),x.algorithm(),x.digits(),x.periodSeconds(),x.createdAt(),x.updatedAt());}}
